/**
 * @param {Array<Function>} functions
 * @return {Promise<Array>}
 */
var promiseAllSettled = function(functions) {
    return new Promise((resolve) => {
        const results = new Array(functions.length);
        let settled = 0;
        if (functions.length === 0) {
            resolve(results);
            return;
        }
        const record = (i, result) => {
            results[i] = result;                                  // keep the original order
            if (++settled === functions.length) resolve(results); // all done
        };
        functions.forEach((fn, i) => {
            try {
                fn().then(
                    (value) => record(i, { status: "fulfilled", value }),
                    (reason) => record(i, { status: "rejected", reason })
                );
            } catch (e) {                                         // fn threw before returning a promise
                record(i, { status: "rejected", reason: e });
            }
        });
    });
};

/**
 * const promise = promiseAllSettled([() => new Promise(res => res(15))]);
 * promise.then(console.log); // [{ status: "fulfilled", value: 15 }]
